Translate("frFR", "durotar", {
	title = "Durotar",
	sections = {
		{
			title = "Résumé",
			text = [=[Durotar est la patrie des orcs, un pays rouge et tourmenté sur la côte est de {link:kalimdor}Kalimdor{/link}. Son sol est craquelé et sec, ses canyons sont acérés, et le soleil s'y abat sans pitié. Les orcs l'ont choisi de bon cœur, car sa beauté rude leur rappelle le monde qu'ils ont perdu. Ici, le chef de guerre {link:thrall}Thrall{/link} a élevé sa capitale, {link:orgrimmar}Orgrimmar{/link}, et ici les jeunes de la {link:horde}Horde{/link} sont mis à l'épreuve avant d'être envoyés de par le monde. C'est une terre en paix de nom seulement. Des ennemis la guettent depuis la mer, depuis les canyons et depuis l'ombre de ses propres grottes.]=],
		},
		{
			title = "Origines",
			text = [=[Avant l'arrivée des orcs, ces terres étaient comptées comme une partie des {link:the-barrens}Tarides{/link}, et les {link:quilboar}hurans{/link} de la {link:razormane-quilboar}tribu Tranchecrin{/link} les parcouraient librement. Après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, {link:thrall}Thrall{/link} mena son peuple vers l'est jusqu'à la côte et revendiqua la terre entre le fleuve Furie-du-Sud et la mer. Il la nomma Durotar, en l'honneur de son père, Durotan, chef du {link:frostwolf-clan}clan Frostwolf{/link}. Les {link:tauren}taurens{/link} et les {link:darkspear-trolls}trolls Darkspear{/link} prêtèrent leur force à la nouvelle nation, et les orcs chassèrent les Tranchecrin de toute la contrée, hormis ses confins occidentaux.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Durotar est le cœur de la nouvelle {link:horde}Horde{/link}. Pourtant, sa paix est fragile. Les humains de {link:kul-tiras}Kul Tiras{/link} tiennent toujours les ruines du {link:tiragarde-keep}Donjon de Tiragarde{/link} sur la côte est. Le féticheur {link:zalazane}Zalazane{/link} règne sur les îles de l'Écho par un vaudou ténébreux. Les {link:razormane-quilboar}Tranchecrin{/link} pressent depuis l'ouest, les {link:centaurs}centaures{/link} {link:kolkar-centaurs}Kolkar{/link} complotent dans leur combe, et les {link:harpies}harpies{/link} Terrevent s'en prennent aux caravanes. Pire que tout, les adeptes de la {link:burning-blade}Lame ardente{/link} se cachent dans les grottes de Durotar, tout près des portes mêmes de la capitale. Depuis peu, même des {link:naga}nagas{/link} ont été aperçus le long de la côte nord.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les orcs.{/b} Ils cultivent la terre dure, montent la garde depuis {link:razor-hill}Tranchecolline{/link} et forment leurs jeunes dans {link:stranglethorn-vale}la Vallée{/link} des épreuves.
• {b}Les trolls {link:darkspear-trolls}Darkspear{/link}.{/b} Chassés de leurs îles, ils ont bâti un village de pêcheurs sur la côte sud et attendent le jour où ils pourront rentrer chez eux.
• {b}Les gobelins.{/b} Des marchands de {link:ratchet}Ratchet{/link} mènent des caravanes sur les routes.
• {b}Les {link:razormane-quilboar}hurans Tranchecrin{/link}.{/b} Ils s'accrochent à leurs camps de ronces à l'ouest et jurent de reprendre ces terres.
• {b}Les humains de {link:kul-tiras}Kul Tiras{/link}.{/b} Des marins et des fusiliers qui servent la mémoire de leur amiral mort.
• {b}La {link:burning-blade}Lame ardente{/link}.{/b} Des adorateurs de démons cachés dans les grottes.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le débarquement.{/b} Après la guerre contre la {link:burning-legion}Légion ardente{/link}, les orcs bâtirent {link:orgrimmar}Orgrimmar{/link} et commencèrent à dompter les terres alentour.
• {b}La guerre de l'amiral.{/b} Peu après, le grand amiral {link:daelin-proudmoore}Daelin Proudmoore{/link} quitta {link:kul-tiras}Kul Tiras{/link} avec une grande flotte, résolu à en finir avec les orcs. Ses hommes élevèrent le {link:tiragarde-keep}Donjon de Tiragarde{/link} sur la côte. Le donjon tomba, et l'amiral lui-même mourut devant les murs de {link:theramore-isle}Theramore{/link}.
• {b}Le traître des îles.{/b} Les {link:darkspear-trolls}Darkspear{/link} s'installèrent sur les îles de l'Écho, mais l'un de leurs propres féticheurs, {link:zalazane}Zalazane{/link}, retourna sa magie contre eux et chassa les trolls libres vers le continent.]=],
		},
		{
			title = "Légendes de la terre rouge",
			text = [=[• Les aspirants chamans de la {link:horde}Horde{/link} boivent un breuvage sacré appelé sapta au {link:spirit-rock}Rocher des esprits{/link}, au-dessus de {link:stranglethorn-vale}la Vallée{/link} des épreuves, et là ils se tiennent devant l'esprit de la terre.
• Les épaves de la flotte de Proudmoore gisent encore dans les hauts-fonds à l'est du {link:tiragarde-keep}Donjon de Tiragarde{/link}. Les orcs de {link:razor-hill}Tranchecolline{/link} envoient des nageurs y chercher des outils humains.
• Une mère de la Ferme de Tor'kren attendit de longs jours son fils, parti chasser les crocilisques du fleuve Furie-du-Sud. Il ne revint pas.]=],
		},
	},
})

Translate("frFR", "valley-of-trials", {
	title = "Vallée des épreuves",
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée des épreuves s'étend au sud-ouest de {link:durotar}Durotar{/link}, enclose de falaises rouges. C'est le terrain d'épreuve de la {link:horde}Horde{/link}. Les jeunes orcs et trolls y viennent affronter leurs premiers ennemis : les sangliers du fond de la vallée, les scorpides des pentes nord, et un scorpide monstrueux nommé Sarkoth. Les instructeurs de la Horde ont leur camp dans une grotte appelée l'Antre. Des péons abattent les rares arbres de la vallée pour le bois, quand ils ne dorment pas. Depuis peu, la vallée est devenue plus dangereuse, car la {link:burning-blade}Lame ardente{/link} a établi un convent dans les grottes de sa paroi nord.]=],
		},
	},
})

Translate("frFR", "burning-blade-coven", {
	title = "Convent de la Lame ardente",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Convent de la Lame ardente est une grotte dans les falaises au nord de {link:stranglethorn-vale}la Vallée{/link} des épreuves. Des mineurs l'ont jadis explorée en quête de minerai. Aujourd'hui, les adeptes de la {link:burning-blade}Lame ardente{/link} l'ont prise, et leurs petits démons, les familiers vils, se déversent de son entrée dans la vallée. Tout au fond, parmi des salles où tombe l'eau, le démoniste {link:yarrog-baneshadow}Yarrog Baneshadow{/link} garde un médaillon d'une sombre puissance. Le convent est petit, mais sa présence si près du terrain d'épreuve de la {link:horde}Horde{/link} est un avertissement : le culte étend son bras plus loin que quiconque le voudrait.]=],
		},
	},
})

Translate("frFR", "spirit-rock", {
	title = "Rocher des esprits",
	aliases = { "Chemin secret" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rocher des esprits se dresse dans les collines, bien au-dessus de {link:stranglethorn-vale}la Vallée{/link} des épreuves, au bout d'un sentier étroit appelé le Chemin secret. C'est une terre sacrée pour les chamans de la {link:horde}Horde{/link}. Ici, les jeunes qui veulent suivre la voie du chaman boivent la sapta, un breuvage qui lie l'esprit aux {link:elements}éléments{/link}, et ici ils voient pour la première fois de leurs propres yeux l'esprit de la terre. Le rite doit être accompli en un lieu sacré, et nulle part ailleurs. Rares sont ceux qui, n'étant pas chamans, gravissent un jour le Chemin secret.]=],
		},
	},
})

Translate("frFR", "razor-hill", {
	title = "Tranchecolline",
	aliases = { "Caserne de Tranchecolline" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tranchecolline est le carrefour de {link:durotar}Durotar{/link}. Ses routes mènent au nord vers {link:orgrimmar}Orgrimmar{/link}, au sud vers {link:stranglethorn-vale}la Vallée{/link} des épreuves et le {link:sen-jin-village}Village de Sen'jin{/link}, et à l'ouest, par-delà le fleuve, vers les {link:the-barrens}Tarides{/link}. C'est une ville de soldats. Depuis sa caserne, {link:gar-thok}Gar'Thok{/link} commande la défense du pays, et {link:orgnil-soulscar}Orgnil Soulscar{/link} traque les adeptes de la {link:burning-blade}Lame ardente{/link}. Un vieux guerrier garde un cor d'alarme sur la tour de guet qui domine la ville. Il le sonne moins souvent qu'autrefois, et il s'en réjouit.]=],
		},
	},
})

Translate("frFR", "sen-jin-village", {
	title = "Village de Sen'jin",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Village de Sen'jin est le foyer des {link:darkspear-trolls}Darkspear{/link} libres, sur la côte sud de {link:durotar}Durotar{/link}. Les trolls le bâtirent après avoir été chassés des îles de l'Écho, et ils lui donnèrent le nom de Sen'jin, le chef qui donna sa vie pour que son peuple puisse suivre les orcs vers une nouvelle terre. C'est un village de huttes et de pontons de pêche. Ses anciens sont féticheurs et alchimistes, ses jeunes sont chasseurs, et ses dresseurs de raptors élèvent des bêtes venues des îles sauvages. Depuis son rivage, les trolls peuvent voir les îles qu'ils ont perdues.]=],
		},
	},
})

Translate("frFR", "echo-isles", {
	title = "Îles de l'Écho",
	sections = {
		{
			title = "Résumé",
			text = [=[Les îles de l'Écho s'étendent au large de la côte sud-est de {link:durotar}Durotar{/link}. Elles devaient être le nouveau foyer des {link:darkspear-trolls}Darkspear{/link}. Elles appartiennent aujourd'hui au féticheur {link:zalazane}Zalazane{/link}, qui tient les trolls des îles asservis par ses maléfices. Ses esclaves errent parmi les huttes, et ses tas de ju-ju souillent le flux de la magie à travers le pays. Des raptors Bloodtalon et des tigres rayés chassent dans la jungle. Sur la plus grande île, un cercle de crânes retient prisonniers les esprits des trolls qui lui ont tenu tête.]=],
		},
	},
})

Translate("frFR", "tiragarde-keep", {
	title = "Donjon de Tiragarde",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Donjon de Tiragarde se dresse sur la côte est de {link:durotar}Durotar{/link}. Les marins de l'amiral {link:daelin-proudmoore}Daelin Proudmoore{/link} l'élevèrent quand leur flotte vint détruire la {link:horde}Horde{/link}. Les orcs prirent le donjon et brisèrent ses murs. Pourtant, après la mort de l'amiral, une force de réserve sous les ordres du lieutenant {link:lieutenant-benedict}Benedict{/link} revint et fortifia de nouveau les ruines. Les fusiliers de {link:kul-tiras}Kul Tiras{/link} y font toujours flotter leur bannière. Dans les décombres autour du donjon gisent les armes des orcs tombés lors du premier assaut, et les leurs voudraient les voir honorés.]=],
		},
	},
})

Translate("frFR", "skull-rock", {
	title = "Rocher du crâne",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rocher du crâne est une grotte dans les montagnes à l'est des portes d'{link:orgrimmar}Orgrimmar{/link}. C'est un repaire de la {link:burning-blade}Lame ardente{/link}. Les adeptes qui s'y trouvent accomplissent d'immondes rites et se brûlent la chair avec des colliers ardents, qui les lient à la puissance démoniaque. Leur maître dans la grotte est le démoniste {link:gazz-uz}Gazz'uz{/link}, qui obéit à une voix parlant à travers un pendentif d'ombre ardente. Que le culte puisse se cacher si près des murs du chef de guerre trouble chaque soldat de la {link:horde}Horde{/link}.]=],
		},
	},
})

Translate("frFR", "drygulch-ravine", {
	title = "Ravin asséché",
	aliases = { "Canyon de Tranchevent" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Canyon de Tranchevent traverse les collines entre {link:razor-hill}Tranchecolline{/link} et {link:orgrimmar}Orgrimmar{/link}, et par une grotte de son flanc est s'ouvre la gorge cachée du Ravin asséché. Tous deux appartiennent aux {link:harpies}harpies{/link} Terrevent. Elles fondent sur les caravanes gobelines de la route, emportent leurs marchandises et les entassent dans leurs nids sur les falaises. Les plus fortes de la volée gardent leurs œufs dans le ravin. Certaines sorcières des harpies ont commencé à jouer avec une étrange magie de tempête.]=],
		},
	},
})

Translate("frFR", "thunder-ridge", {
	title = "Falaises du Tonnerre",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Falaises du Tonnerre sont une gorge boisée au nord-ouest de {link:durotar}Durotar{/link}, au sud d'{link:orgrimmar}Orgrimmar{/link}. Elles doivent leur nom aux lézards-tonnerre qui les parcourent, de grandes bêtes dont le corps renferme une charge de foudre. Le démoniste gobelin Fizzle Darkstorm y a établi un camp avec des adeptes de la {link:burning-blade}Lame ardente{/link}, et ils sèment le chaos parmi les arbres. Les orcs chassent les lézards pour leurs peaux, qui garnissent les toits de la capitale en pleine croissance. Le plus puissant d'entre eux se nomme Halikor, et son sabot est un trophée dont on peut se vanter.]=],
		},
	},
})

Translate("frFR", "kolkar-crag", {
	title = "Combe des Kolkar",
	sections = {
		{
			title = "Résumé",
			text = [=[La Combe des Kolkar est une gorge rocheuse au sud de {link:durotar}Durotar{/link}, à l'ouest du {link:sen-jin-village}Village de Sen'jin{/link}. Les {link:centaurs}centaures{/link} {link:kolkar-centaurs}Kolkar{/link} en ont fait leur camp. Ils lancent des raids de nuit, et leur seigneur de guerre, Kolkanis, a dressé des plans pour frapper les orcs et les trolls du pays. Un éclaireur troll de la {link:horde}Horde{/link} se glissa un jour dans la combe et lut ces plans de ses propres yeux. D'autres qui ont tenté d'explorer la combe seuls n'en sont pas toujours ressortis.]=],
		},
	},
})

Translate("frFR", "razormane-grounds", {
	title = "Terres des Tranchecrins",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Terres des Tranchecrins s'étendent à l'ouest de {link:durotar}Durotar{/link}, là où le terrain descend vers le fleuve Furie-du-Sud. Ici, les {link:quilboar}hurans{/link} de la {link:razormane-quilboar}tribu Tranchecrin{/link} ont leurs camps de ronces. Ils tenaient une grande partie de Durotar avant l'arrivée des orcs, et ils n'ont jamais accepté cette perte. Des os rongés jonchent le sol autour de leurs épines. Leurs géomanciens invoquent la terre, et leurs gardes de guerre défendent les camps avec une fureur née de l'orgueil blessé. Les orcs de {link:razor-hill}Tranchecolline{/link} ont juré de les chasser de Durotar, et après cela, peut-être, de {link:kalimdor}Kalimdor{/link}.]=],
		},
	},
})

Translate("frFR", "darkspear-islands", {
	title = "Darkspear Islands",
	aliases = { "Îles Darkspear" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les îles {link:darkspear-trolls}Darkspear{/link} s'étendent au large de la côte de {link:durotar}Durotar{/link}, battues par les tempêtes de la haute mer. Les trolls les tiennent pour sacrées, car leurs esprits y sont puissants, et les Darkspear s'y rassemblent pour leurs cérémonies. Aujourd'hui, l'{link:alliance}Alliance{/link} cherche à prendre pied sur ces îles, tout près des rivages de la patrie des orcs. Les Darkspear et leurs alliés de la {link:horde}Horde{/link} ne la laisseront pas s'y installer. Parmi des ruines, un camp, une vieille tour et une crique jonchée d'épaves, les deux camps se disputent le contrôle des îles et d'une relique sacrée de la tribu.]=],
		},
	},
})

Translate("frFR", "kaltunk", {
	title = "Kaltunk",
	subtitle = "Accueil des recrues",
	found = "L'Antre, dans la Vallée des épreuves",
	hint = [=[Parlez à l'orc qui accueille les jeunes recrues de la Vallée des épreuves.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Kaltunk accueille les jeunes orcs et trolls qui atteignent l'âge adulte dans {link:stranglethorn-vale}la Vallée{/link} des épreuves. Il toise chacun d'un œil critique et d'un large sourire. Il sait que chaque recrue rêve d'étrangler un dragon dès le premier jour, et il prend plaisir à leur dire de commencer par quelque chose de plus petit. Puis il rit, et leur montre l'Antre.]=],
		},
		{
			title = "Importance",
			text = [=[Kaltunk est la première voix de la {link:horde}Horde{/link} que beaucoup de ses jeunes entendent. C'est lui qui leur dit qu'ils sont enfin assez âgés pour combattre au nom du chef de guerre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie chaque nouvelle recrue auprès de {link:gornek}Gornek{/link}, dans l'Antre.]=],
		},
	},
	mentions = {
		{ text = "Votre place dans le monde" },
	},
	bonds = {
		{ id = "gornek", name = "Gornek", note = "reçoit ses recrues" },
	},
})

Translate("frFR", "gornek", {
	title = "Gornek",
	subtitle = "Maître de l'Antre",
	found = "L'Antre, dans la Vallée des épreuves",
	hint = [=[Parlez à l'orc qui assigne les premières épreuves dans l'Antre.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Gornek assigne les épreuves de {link:stranglethorn-vale}la Vallée{/link}. Il est bourru et difficile à satisfaire, et il accueille chaque recrue comme si la {link:horde}Horde{/link} était tombée bien bas pour lui envoyer pareil matériau. Pourtant, il les observe de près. Il les envoie d'abord contre les sangliers de la vallée, puis contre ses scorpides, et il enseigne que même le plus petit ennemi peut donner la mort.]=],
		},
		{
			title = "Importance",
			text = [=[Gornek fait des jeunes des guerriers de la {link:horde}Horde{/link}. Ses éloges sont rares, et on s'en souvient.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il met les recrues à l'épreuve contre les sangliers tachetés et les scorpides de la vallée.
• Il envoie de l'aide au troll blessé {link:hana-zua}Hana'zua{/link}.
• Il fait rassembler les armes abandonnées des recrues qui ont échoué et les fait rendre au forgeron.]=],
		},
	},
	mentions = {
		{ text = "Se faire les dents" },
		{ text = "La piqûre du scorpide" },
		{ text = "Sarkoth, selon le récit d'{link:hana-zua}Hana'zua{/link}" },
		{ text = "Armes égarées" },
	},
	bonds = {
		{ id = "kaltunk", name = "Kaltunk", note = "lui envoie des recrues" },
		{ id = "zureetha-fargaze", name = "Zureetha Fargaze", note = "partage son camp" },
		{ id = "hana-zua", name = "Hana'zua", note = "le troll blessé qu'il secourt" },
	},
})

Translate("frFR", "zureetha-fargaze", {
	title = "Zureetha Fargaze",
	subtitle = "Voyante de la Vallée",
	found = "Devant l'Antre, dans la Vallée des épreuves",
	hint = [=[Parlez à l'orque qui lit les signes de la Vallée des épreuves.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Zureetha Fargaze fut envoyée dans {link:stranglethorn-vale}la Vallée{/link} des épreuves pour guider ses recrues. Elle y trouva plutôt une souillure. Par ses divinations, elle apprit que la {link:burning-blade}Lame ardente{/link} avait établi un convent dans les grottes de la vallée, et qu'un objet d'une sombre puissance y était caché. Elle craint que ce ne soit que le signe annonciateur d'un mal plus grand.]=],
		},
		{
			title = "Importance",
			text = [=[Zureetha est la première en {link:durotar}Durotar{/link} à voir l'ombre de la {link:burning-blade}Lame ardente{/link}, et elle en fait porter la nouvelle à travers le pays.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle envoie des recrues contre les familiers vils du convent.
• Elle fait prendre le médaillon de la {link:burning-blade}Lame ardente{/link} aux adeptes.
• Elle envoie son rapport à maître Gadrin, au {link:sen-jin-village}Village de Sen'jin{/link}.]=],
		},
	},
	mentions = {
		{ text = "Familiers vils" },
		{ text = "Le médaillon de la {link:burning-blade}Lame ardente{/link}" },
		{ text = "Rapport au {link:sen-jin-village}Village de Sen'jin{/link}" },
	},
	bonds = {
		{ id = "yarrog-baneshadow", name = "Yarrog Baneshadow", note = "gardait le médaillon" },
		{ id = "master-gadrin", name = "Maître Gadrin", note = "reçoit son rapport" },
		{ id = "gornek", name = "Gornek", note = "partage son camp" },
	},
})

Translate("frFR", "hana-zua", {
	title = "Hana'zua",
	subtitle = "Chasseur blessé des Darkspear",
	found = "Le plateau au sud de l'Antre",
	hint = [=[Trouvez le troll blessé qui gît sur le plateau au sud de l'Antre.]=],
	allegiance = "Trolls Darkspear",
	sections = {
		{
			title = "Résumé",
