Translate("frFR", "daelin-proudmoore", {
	title = "Daelin Proudmoore",
	subtitle = "Grand amiral de Kul Tiras",
	allegiance = "Kul Tiras · Maison Proudmoore",
	aliases = { "Daelin", "amiral Proudmoore" },
	sections = {
		{
			title = "Résumé",
			text = [=[Daelin Proudmoore était le lord amiral de {link:kul-tiras}Kul Tiras{/link} et le père de {link:jaina-proudmoore}Jaina Proudmoore{/link}. Durant la {link:second-war}Deuxième Guerre{/link}, ses flottes régnèrent sur les mers pour l'{link:alliance}Alliance{/link}, et il devint l'un des grands héros de l'humanité. Il ne pardonna jamais cette guerre aux orcs. Quand il apprit qu'ils s'étaient installés sur les rivages de {link:kalimdor}Kalimdor{/link}, il vint avec une armada pour les détruire, et il mourut dans cette entreprise.]=],
		},
		{
			title = "Importance",
			text = [=[La guerre de Daelin fut la première grande menace pour la jeune nation de {link:durotar}Durotar{/link}. Sa mort traça une ligne entre le père et la fille, et entre deux manières de voir les orcs : comme un peuple capable de changer, ou comme des monstres qui ne changeraient jamais. Ses hommes tiennent toujours le {link:tiragarde-keep}Donjon de Tiragarde{/link} en son nom.]=],
		},
		{
			title = "L'amiral de l'Alliance",
			text = [=[{link:kul-tiras}Kul Tiras{/link} était un royaume de marins, et la maison Proudmoore menait ses flottes. Quand la {link:horde}Horde{/link} marcha vers le nord après la {link:first-war}Première Guerre{/link}, Daelin fit entrer sa marine dans l'{link:alliance}Alliance{/link} de {link:lordaeron}Lordaeron{/link}. Ses navires combattirent les flottes orques en haute mer et transportèrent les armées de l'Alliance d'un rivage à l'autre. Kul Tiras paya cher en navires et en hommes. Daelin se souvint de ce prix pour le reste de sa vie.]=],
		},
		{
			title = "L'armada",
			text = [=[Après la {link:third-war}Troisième Guerre{/link}, sa fille {link:jaina-proudmoore}Jaina{/link} mena les survivants de {link:lordaeron}Lordaeron{/link} vers l'ouest jusqu'en {link:kalimdor}Kalimdor{/link} et bâtit la {link:theramore-isle}cité de Theramore{/link}. Là, elle fit la paix avec {link:thrall}Thrall{/link}. Daelin ne voulut pas l'accepter. Il fit voile vers Kalimdor avec une grande flotte, éleva le {link:tiragarde-keep}Donjon de Tiragarde{/link} sur la côte de {link:durotar}Durotar{/link}, et fit la guerre aux orcs et aux trolls des îles de l'Écho. La {link:horde}Horde{/link} répondit. Ses guerriers brisèrent le donjon, et portèrent enfin le combat jusqu'aux murs mêmes de Theramore. Jaina se tint à l'écart. Dans les combats, l'amiral fut tué.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il commanda la marine de {link:kul-tiras}Kul Tiras{/link} durant la {link:second-war}Deuxième Guerre{/link}.
• Il éleva le {link:tiragarde-keep}Donjon de Tiragarde{/link} sur les rivages de {link:durotar}Durotar{/link}.
• Il fit la guerre à la {link:horde}Horde{/link} au mépris de la paix conclue par sa fille.
• Il laissa des ordres pour une guerre qui devait se poursuivre après sa mort.]=],
		},
		{
			title = "Non consigné",
			text = [=[Peu de choses sont écrites ici sur la vie de Daelin avant les guerres. Cette entrée ne rapporte que ce que révèlent les histoires et ses propres ordres.]=],
		},
	},
	chapters = {
		{
			title = "Les ordres de l'amiral",
			hint = "Lisez les ordres scellés gardés au Donjon de Tiragarde.",
			text = [=[Parmi les affaires du lieutenant {link:lieutenant-benedict}Benedict{/link} se trouvait une vieille enveloppe portant le sceau de l'amiral. Elle contenait des ordres écrits avant même que Daelin ne quitte {link:kul-tiras}Kul Tiras{/link}. Ils montraient qu'il avait bien préparé ses plans, et que d'autres de ses hommes devaient suivre la première flotte jusqu'en {link:durotar}Durotar{/link}. Les orcs de {link:razor-hill}Tranchecolline{/link} y lurent un avertissement simple : l'amiral était mort, mais sa guerre ne l'était pas.]=],
		},
	},
	mentions = {
		{ text = "Vaincre les traîtres" },
		{
			text = [=[Les ordres de l'amiral, portés à {link:gar-thok}Gar'Thok{/link}]=],
		},
		{
			text = [=[Les ordres de l'amiral, portés à {link:orgrimmar}Orgrimmar{/link}]=],
		},
	},
	bonds = {
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "sa fille" },
		{ id = "lieutenant-benedict", name = "Lieutenant Benedict", note = "poursuit sa guerre" },
		{ id = "thrall", name = "Thrall", note = "son ennemi" },
	},
})
